-- Indonesia deep-dive ES/DE/FR translations (completing 359).
-- INSERT OR IGNORE throughout.

-- ==================== es ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'es', 'Verificación (clearance) de la DJP en tiempo real a través de Coretax desde el 31 de diciembre de 2025, tras un mandato de e-Faktur escalonado que alcanzó cobertura nacional en 2016', 'Esta página de análisis refleja la orientación pública de la DJP y la información del sector disponible a principios de agosto de 2026, y se ofrece a título informativo general, no como asesoramiento legal o fiscal. Confirme los requisitos vigentes directamente con la DJP o con un asesor fiscal indonesio antes de basar en esta página sus decisiones de cumplimiento.', 'El sistema e-Faktur Pajak de Indonesia exigió facturas electrónicas de IVA por etapas desde 2014, alcanzando cobertura nacional completa el 1 de julio de 2016. La plataforma Coretax de la DJP se lanzó el 1 de enero de 2025 y pasó a estar plenamente vigente desde el 31 de diciembre de 2025, llevando a Indonesia a un auténtico modelo de clearance en tiempo real en el que la aprobación de la DJP es un requisito legal previo para que una factura sea válida.', 'Las facturas de Coretax se crean en XML y se cargan para su validación en tiempo real por parte de la DJP; una vez aprobadas, la factura se emite al comprador como un PDF con código QR que incluye un Número de Serie de Factura Fiscal (Nomor Seri Faktur Pajak, NSFP) generado automáticamente. Las empresas pueden acceder a Coretax a través de su portal web, un cliente de escritorio o una integración Host-to-Host (H2H) para sistemas contables empresariales. Las facturas en papel solo se permiten durante interrupciones confirmadas del sistema -- en cualquier otro caso, toda factura fiscal debe pasar por este proceso electrónico validado por la DJP.', 'El mandato de facturación electrónica de Indonesia es prácticamente universal: todo contribuyente registrado a efectos de IVA (Pengusaha Kena Pajak, PKP) está dentro del alcance, cubriendo los suministros gravables B2B y B2G nacionales, las facturas de exportación (emitidas como facturas de IVA a tipo cero) y los documentos correctivos como notas de crédito, notas de débito y anulaciones. No existe una exención para pequeñas empresas o por sector comparable a la de otros países cubiertos por este seguimiento -- el propio registro como PKP es lo que hace entrar a una empresa en el alcance.', 'Dado que la plena vigencia de Coretax es reciente -- efectiva solo desde el 31 de diciembre de 2025 --, la mayoría de los PKP todavía tienen trabajo real de implementación por delante, ya sea confirmar que su configuración de e-Faktur existente migró correctamente o construir un primer flujo de facturación conectado a Coretax.', 'Indonesia respalda sus normas de facturación electrónica y reporte de IVA con sanciones reales y documentadas, que van desde la pérdida del crédito fiscal por una factura cargada con retraso hasta multas que escalan según la magnitud de un impago.', 'Indonesia exige facturas electrónicas de IVA desde 2014, alcanzando la cobertura nacional de e-Faktur el 1 de julio de 2016. La plataforma Coretax de la DJP se lanzó el 1 de enero de 2025, y la PER-11/PJ/2025 trasladó el plazo de carga de facturas al día 20 del mes siguiente. A partir del 31 de diciembre de 2025, Coretax pasó a estar plenamente vigente: el visto bueno de la DJP es ahora un requisito legal previo para que una factura sea válida, y no una comprobación posterior a su creación. Las facturas sin aprobar no pueden sustentar las deducciones del IVA soportado, y el reporte incorrecto puede acarrear sanciones de hasta el 100% del IVA impagado.', '🇮🇩' FROM countries WHERE name_en = 'Indonesia';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '1 jul 2016', 'El e-Faktur se vuelve obligatorio en todo el país' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Indonesia' AND s.sort_order = 0;
