INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '31 dic 2025', 'Coretax pasa a estar plenamente vigente -- el visto bueno de la DJP se vuelve obligatorio' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Indonesia' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', 'Hasta el 100%', 'Sanción por reporte incorrecto o impago de IVA' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Indonesia' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', 'Todo PKP registrado a efectos de IVA', 'Alcance del mandato de Coretax' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Indonesia' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Formato y estándar', '[["Creación de la factura", "XML, generado a través de Coretax o de software conectado a Coretax"], ["Validación", "Validación en tiempo real por parte de la DJP antes de que la factura se emita legalmente"], ["Formato de entrega", "PDF con código QR, con un Número de Serie de Factura Fiscal (NSFP) generado automáticamente"], ["Canales de acceso", "Portal web de Coretax, cliente de escritorio o integración Host-to-Host (H2H) para sistemas empresariales"]]', 'Las facturas en papel solo se permiten durante interrupciones confirmadas del sistema -- trate la emisión electrónica a través de uno de los canales de Coretax como la norma, no como la excepción.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Indonesia' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Identificadores y registro', '[["Registro del contribuyente", "Pengusaha Kena Pajak (PKP) -- el registro a efectos de IVA ante la DJP es lo que activa el alcance de la facturación electrónica"], ["Cuenta Coretax", "Registrada y activada a través del portal Coretax DJP"], ["Número de serie", "Nomor Seri Faktur Pajak (NSFP), generado automáticamente por Coretax al aprobarse"], ["Organismo responsable", "Direktorat Jenderal Pajak (DJP) -- Dirección General de Impuestos, Ministerio de Finanzas"]]', 'Las empresas extranjeras que se registran a efectos del IVA indonesio entran en el alcance en las mismas condiciones que los PKP nacionales una vez registradas.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Indonesia' AND cd.section = 'file_format' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Contenido obligatorio y conservación', '[["Campos esenciales de la factura", "Identificación fiscal del emisor/comprador, fecha de la factura, bienes/servicios e importes de IVA detallados, NSFP"], ["Base legal", "Reglamentos de la DJP dentro del marco de la Ley del IVA de Indonesia, incluida la PMK 131/Tahun 2024"], ["Documentos correctivos", "Las notas de crédito, notas de débito y anulaciones también deben procesarse a través de Coretax"], ["Conservación", "Conforme a las normas generales de conservación de documentos contables/fiscales de Indonesia bajo la Ley de Disposiciones Generales Tributarias (normalmente 10 años) -- confirme el plazo vigente con la DJP o con un asesor local"]]', 'No trate la PMK 131/Tahun 2024 como la única base legal de cada norma aquí descrita -- la DJP ha superpuesto varios reglamentos (KEP-54/PJ/2025, PER-11/PJ/2025, PER-8/PJ/2025) sobre el marco básico de la Ley del IVA.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Indonesia' AND cd.section = 'file_format' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'es', 'El flujo de clearance de Coretax', 'Una factura fiscal recorre esta secuencia bajo Coretax -- la validación de la DJP ahora ocurre antes de que la factura sea legalmente válida, no después:', 'Se trata de un auténtico modelo de clearance: a diferencia de las comprobaciones posteriores a la creación del antiguo sistema e-Faktur, una factura no tiene efecto legal -- ni puede sustentar el crédito fiscal de IVA del comprador -- hasta que la DJP la aprueba.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Indonesia';
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'El vendedor genera la factura fiscal en XML a través de Coretax (portal web, cliente de escritorio o integración Host-to-Host)' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Indonesia' AND st.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'La factura se carga en Coretax para su validación en tiempo real por parte de la DJP' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Indonesia' AND st.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'La DJP valida la factura y le asigna un Número de Serie de Factura Fiscal (NSFP)' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Indonesia' AND st.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'Coretax emite una versión en PDF con código QR de la factura aprobada' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Indonesia' AND st.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'La factura es legalmente válida y se entrega al comprador -- solo entonces puede sustentar el crédito fiscal de IVA del comprador' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Indonesia' AND st.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Qué es obligatorio hoy, por capas', '[["Emisión nacional de e-Faktur", "Todo PKP, desde el 1 de julio de 2016"], ["Clearance en tiempo real de Coretax", "Todo PKP, obligatorio desde el 31 de diciembre de 2025"], ["Canales H2H/Desktop para grandes contribuyentes", "Siguen permitidos, pero ahora alimentan el clearance de Coretax en lugar de operar de forma independiente"], ["Facturas en papel", "Solo permitidas durante interrupciones confirmadas del sistema"]]', 'Conviene precisar qué capa le aplica: el mandato de facturación electrónica de Indonesia es realmente universal desde 2016, pero el requisito de clearance -- la aprobación de la DJP antes de que una factura sea válida -- solo pasó a estar plenamente vigente a partir del 31 de diciembre de 2025.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Indonesia' AND cd.section = 'scope_transmission' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Quién debe cumplir', '[["Registro como PKP", "Toda empresa que supere el umbral de registro de IVA de Indonesia debe registrarse como PKP y cumplir"], ["B2B y B2G nacionales", "Plenamente incluidos -- suministros gravables de bienes y servicios"], ["Facturas de exportación", "Incluidas, emitidas como facturas de IVA a tipo cero"], ["Documentos correctivos", "Las notas de crédito, notas de débito y anulaciones también deben procesarse a través de Coretax"]]', 'No existe una exención general para pequeñas empresas frente a Coretax comparable a la de otros países de este seguimiento -- el propio registro como PKP es el detonante.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Indonesia' AND cd.section = 'scope_transmission' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '💰 Si pierde el plazo de carga del día 20, pierde el crédito de IVA', NULL, NULL, 'Desde la PER-11/PJ/2025 (22 de mayo de 2025), las facturas fiscales deben cargarse en Coretax antes del día 20 del mes siguiente a su emisión. Si se incumple ese plazo, el comprador pierde la posibilidad de reclamar el crédito fiscal de IVA soportado en la factura -- una consecuencia financiera inmediata para el comprador, no solo un descuido administrativo del vendedor.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Indonesia' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '⚠️ Multas por no emitir facturas electrónicas y por declaraciones de IVA tardías', NULL, NULL, 'El incumplimiento de la obligación de emitir facturas electrónicas conlleva multas administrativas. Por separado, la presentación tardía de la declaración periódica de IVA (SPT Masa PPN) conlleva una multa fija de 500.000 IDR -- un coste habitual pero real por incumplir un plazo de presentación, independiente de cualquier sanción a nivel de factura.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Indonesia' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '🔒 Las facturas sin aprobar no pueden sustentar el crédito fiscal', NULL, NULL, 'Desde que Coretax pasó a estar plenamente vigente el 31 de diciembre de 2025, el visto bueno de la DJP es un requisito legal previo para que una factura fiscal sea válida. Una factura que la DJP no haya aprobado no puede sustentar la deducción del IVA soportado del comprador, y el reporte incorrecto o el impago del IVA pueden acarrear sanciones de hasta el 100% del importe impagado -- una exposición real y significativa, no nominal.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Indonesia' AND cd.section = 'penalties_related' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'es', 'Presentación tardía de la declaración periódica de IVA (SPT Masa PPN)', '500.000 IDR (fija)', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Indonesia' AND pr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'es', 'Reporte incorrecto o impago de IVA', 'Hasta el 100% del importe de IVA impagado', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Indonesia' AND pr.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Confirme que su registro como PKP y su cuenta Coretax están activos', 'Todo contribuyente registrado a efectos de IVA (PKP) necesita una cuenta Coretax activa -- confirme que la suya está registrada y accesible antes de depender de ella para la emisión de facturas.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Indonesia' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Traslade su flujo de facturación a un canal conectado a Coretax', 'Ya sea a través del portal web, el cliente de escritorio o una integración Host-to-Host (H2H), confirme que su software de facturación realmente envía a Coretax en lugar de depender de un proceso heredado independiente.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Indonesia' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Cargue toda factura en Coretax antes del día 20 del mes siguiente', 'La PER-11/PJ/2025 fijó este plazo como estricto -- incumplirlo le cuesta al comprador su crédito fiscal de IVA, así que trátelo como un plazo de cumplimiento, no como un objetivo flexible.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Indonesia' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Incorpore una comprobación de clearance de la DJP en tiempo real en su proceso de emisión de facturas', 'Desde el 31 de diciembre de 2025, una factura no tiene efecto legal hasta que la DJP la aprueba -- confirme que su proceso espera esa aprobación antes de considerar una factura como definitiva.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Indonesia' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Confirme que su proceso de cuentas por pagar rechaza las facturas de proveedores sin clearance válido de Coretax', 'Una factura de proveedor sin la aprobación de la DJP y un NSFP válido no puede sustentar su crédito fiscal de IVA -- incorpore esa comprobación en su flujo de cuentas por pagar, no solo en su propio proceso de ventas.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Indonesia' AND sp.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Mantenga un plan de contingencia de facturas en papel limitado estrictamente a interrupciones confirmadas del sistema', 'La facturación en papel solo se permite durante interrupciones genuinas de Coretax -- no deje que se convierta en una solución habitual para una incorporación lenta o problemas técnicos sin resolver.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Indonesia' AND sp.sort_order = 5;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'es', 'Coretax DJP — plataforma de clearance de facturas electrónicas en tiempo real y operaciones de IVA' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Indonesia' AND pt.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'es', 'Direktorat Jenderal Pajak (DJP) — Dirección General de Impuestos' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Indonesia' AND pt.sort_order = 1;

-- ==================== de ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'de', 'Echtzeit-Freigabe (Clearance) durch die DJP über Coretax seit dem 31. Dezember 2025, nach einer stufenweisen e-Faktur-Pflicht, die 2016 landesweite Abdeckung erreichte', 'Diese Analyseseite spiegelt öffentlich verfügbare Hinweise der DJP und Brancheninformationen mit Stand Anfang August 2026 wider und dient allgemeinen Informationszwecken, nicht als Rechts- oder Steuerberatung. Bestätigen Sie aktuelle Anforderungen direkt bei der DJP oder einem indonesischen Steuerberater, bevor Sie sich bei Compliance-Entscheidungen auf diese Seite verlassen.', 'Indonesiens e-Faktur-Pajak-System verlangte ab 2014 stufenweise elektronische USt-Rechnungen und erreichte bis zum 1. Juli 2016 vollständige landesweite Abdeckung. Die Coretax-Plattform der DJP ging am 1. Januar 2025 an den Start und wurde ab dem 31. Dezember 2025 vollständig durchgesetzt -- damit wechselte Indonesien zu einem echten Echtzeit-Freigabemodell, bei dem die Genehmigung der DJP eine rechtliche Voraussetzung für eine gültige Rechnung ist.', 'Coretax-Rechnungen werden im XML-Format erstellt und zur Echtzeitvalidierung durch die DJP hochgeladen; nach Genehmigung wird die Rechnung dem Käufer als PDF mit QR-Code ausgestellt, das eine automatisch generierte Steuerrechnungs-Seriennummer (Nomor Seri Faktur Pajak, NSFP) trägt. Unternehmen können auf Coretax über das Webportal, einen Desktop-Client oder eine Host-to-Host-Integration (H2H) für Unternehmensbuchhaltungssysteme zugreifen. Papierrechnungen sind nur bei bestätigten Systemausfällen zulässig -- andernfalls muss jede Steuerrechnung diesen elektronischen, DJP-validierten Prozess durchlaufen.', 'Indonesiens E-Rechnungspflicht ist nahezu universell: Jeder umsatzsteuerlich registrierte Steuerpflichtige (Pengusaha Kena Pajak, PKP) fällt darunter, einschließlich inländischer B2B- und B2G-steuerpflichtiger Lieferungen, Exportrechnungen (ausgestellt als nullbesteuerte USt-Rechnungen) und Korrekturdokumente wie Gutschriften, Lastschriften und Stornierungen. Es gibt keine mit anderen von diesem Tracker erfassten Ländern vergleichbare Ausnahme für Kleinunternehmen oder bestimmte Sektoren -- die Registrierung als PKP selbst bringt ein Unternehmen in den Anwendungsbereich.', 'Da die vollständige Durchsetzung von Coretax erst seit dem 31. Dezember 2025 gilt, liegt vor den meisten PKP noch echte Umsetzungsarbeit -- sei es die Bestätigung, dass ihre bestehende e-Faktur-Einrichtung korrekt migriert wurde, oder der Aufbau eines ersten mit Coretax verbundenen Rechnungsworkflows.', 'Indonesien untermauert seine E-Rechnungs- und USt-Meldevorschriften mit realen, belegten Sanktionen -- vom Verlust des Vorsteuerabzugs bei einer verspätet hochgeladenen Rechnung bis zu Bußgeldern, die mit der Höhe einer Unterzahlung skalieren.', 'Indonesien verlangt elektronische USt-Rechnungen seit 2014 und erreichte bis zum 1. Juli 2016 landesweite e-Faktur-Abdeckung. Die Coretax-Plattform der DJP ging am 1. Januar 2025 an den Start, und die PER-11/PJ/2025 verschob die Frist für den Rechnungsupload auf den 20. des Folgemonats. Ab dem 31. Dezember 2025 wurde Coretax vollständig durchgesetzt: Die Freigabe der DJP ist nun eine rechtliche Voraussetzung für eine gültige Rechnung, keine nachträgliche Prüfung. Nicht freigegebene Rechnungen können den USt-Vorsteuerabzug nicht stützen, und fehlerhafte Meldungen können Strafen von bis zu 100 % des nicht gezahlten Betrags nach sich ziehen.', '🇮🇩' FROM countries WHERE name_en = 'Indonesia';

