INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '31. Dez. 2025', 'Coretax vollständig durchgesetzt -- DJP-Freigabe wird verpflichtend' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Indonesia' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', 'Bis zu 100%', 'Strafe für fehlerhafte USt-Meldung oder Unterzahlung' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Indonesia' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', 'Alle umsatzsteuerlich registrierten PKP', 'Umfang der Coretax-Pflicht' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Indonesia' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Format & Standard', '[["Rechnungserstellung", "XML, erstellt über Coretax oder mit Coretax verbundene Software"], ["Validierung", "Echtzeitvalidierung durch die DJP, bevor die Rechnung rechtsgültig ausgestellt wird"], ["Übermittlungsformat", "PDF mit QR-Code, das eine automatisch generierte Steuerrechnungs-Seriennummer (NSFP) trägt"], ["Zugangskanäle", "Coretax-Webportal, Desktop-Client oder Host-to-Host-Integration (H2H) für Unternehmenssysteme"]]', 'Papierrechnungen bleiben nur bei bestätigten Systemausfällen zulässig -- betrachten Sie die elektronische Ausstellung über einen der Coretax-Kanäle als Standard, nicht als Ausnahme.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Indonesia' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Kennungen & Registrierung', '[["Steuerpflichtigen-Registrierung", "Pengusaha Kena Pajak (PKP) -- die umsatzsteuerliche Registrierung bei der DJP löst die E-Rechnungspflicht aus"], ["Coretax-Konto", "Registriert und aktiviert über das Coretax-DJP-Portal"], ["Seriennummer", "Nomor Seri Faktur Pajak (NSFP), von Coretax bei Genehmigung automatisch generiert"], ["Zuständige Behörde", "Direktorat Jenderal Pajak (DJP) -- Generaldirektion für Steuern, Finanzministerium"]]', 'Ausländische Unternehmen, die sich für die indonesische Umsatzsteuer registrieren, fallen nach der Registrierung auf derselben Grundlage wie inländische PKP in den Anwendungsbereich.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Indonesia' AND cd.section = 'file_format' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Pflichtinhalt & Aufbewahrung', '[["Kernrechnungsfelder", "Steuerliche Identifikation von Aussteller/Käufer, Rechnungsdatum, aufgeschlüsselte Waren/Dienstleistungen und USt-Beträge, NSFP"], ["Rechtsgrundlage", "DJP-Verordnungen im Rahmen des indonesischen Umsatzsteuergesetzes, einschließlich der PMK 131/Tahun 2024"], ["Korrekturdokumente", "Gutschriften, Lastschriften und Stornierungen müssen ebenfalls über Coretax verarbeitet werden"], ["Aufbewahrung", "Entsprechend den allgemeinen indonesischen Aufbewahrungsvorschriften für Buchhaltungs-/Steuerunterlagen nach dem Gesetz über allgemeine Steuervorschriften (in der Regel 10 Jahre) -- bestätigen Sie die aktuelle Frist bei der DJP oder einem lokalen Berater"]]', 'Betrachten Sie die PMK 131/Tahun 2024 nicht als alleinige Rechtsgrundlage für jede hier genannte Regel -- die DJP hat mehrere Verordnungen (KEP-54/PJ/2025, PER-11/PJ/2025, PER-8/PJ/2025) auf das grundlegende Umsatzsteuergesetz aufgesetzt.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Indonesia' AND cd.section = 'file_format' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'de', 'Der Coretax-Freigabeablauf', 'Eine Steuerrechnung durchläuft unter Coretax diese Abfolge -- die DJP-Validierung erfolgt nun vor, nicht nach der Rechtsgültigkeit der Rechnung:', 'Dies ist ein echtes Freigabemodell: Anders als bei den nachträglichen Prüfungen des alten e-Faktur-Systems hat eine Rechnung keine Rechtswirkung -- und kann den USt-Vorsteuerabzug des Käufers nicht stützen --, bis die DJP sie freigibt.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Indonesia';
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'Der Verkäufer erstellt die Steuerrechnung im XML-Format über Coretax (Webportal, Desktop-Client oder Host-to-Host-Integration)' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Indonesia' AND st.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'Die Rechnung wird zur Echtzeitvalidierung durch die DJP auf Coretax hochgeladen' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Indonesia' AND st.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'Die DJP validiert die Rechnung und vergibt eine Steuerrechnungs-Seriennummer (NSFP)' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Indonesia' AND st.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'Coretax stellt eine PDF-Version der freigegebenen Rechnung mit QR-Code aus' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Indonesia' AND st.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'Die Rechnung ist rechtsgültig und wird an den Käufer ausgeliefert -- erst jetzt kann sie den USt-Vorsteuerabzug des Käufers stützen' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Indonesia' AND st.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Was heute verpflichtend ist, nach Ebenen', '[["Landesweite e-Faktur-Ausstellung", "Alle PKP, seit 1. Juli 2016"], ["Echtzeit-Freigabe durch Coretax", "Alle PKP, verpflichtend seit 31. Dezember 2025"], ["H2H-/Desktop-Kanäle für Großsteuerpflichtige", "Weiterhin zulässig, fließen aber nun in die Freigabe von Coretax ein, statt unabhängig zu arbeiten"], ["Papierrechnungen", "Nur bei bestätigten Systemausfällen zulässig"]]', 'Es lohnt sich, genau zu klären, welche Ebene für Sie gilt: Indonesiens E-Rechnungspflicht ist bereits seit 2016 wirklich universell, doch die Freigabepflicht -- die Genehmigung der DJP vor Gültigkeit einer Rechnung -- wurde erst ab dem 31. Dezember 2025 vollständig durchgesetzt.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Indonesia' AND cd.section = 'scope_transmission' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Wer verpflichtet ist', '[["PKP-Registrierung", "Jedes Unternehmen, das Indonesiens umsatzsteuerliche Registrierungsschwelle überschreitet, muss sich als PKP registrieren und die Vorgaben einhalten"], ["Inländisches B2B und B2G", "Vollständig erfasst -- steuerpflichtige Lieferungen von Waren und Dienstleistungen"], ["Exportrechnungen", "Erfasst, ausgestellt als nullbesteuerte USt-Rechnungen"], ["Korrekturdokumente", "Gutschriften, Lastschriften und Stornierungen müssen ebenfalls über Coretax verarbeitet werden"]]', 'Es gibt keine allgemeine Kleinunternehmerausnahme von Coretax, vergleichbar mit anderen erfassten Ländern -- die PKP-Registrierung selbst ist der Auslöser.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Indonesia' AND cd.section = 'scope_transmission' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '💰 Wer die Hochladefrist zum 20. verpasst, verliert den Vorsteuerabzug', NULL, NULL, 'Seit der PER-11/PJ/2025 (22. Mai 2025) müssen Steuerrechnungen bis zum 20. des auf die Ausstellung folgenden Monats auf Coretax hochgeladen werden. Wird diese Frist verpasst, verliert der Käufer die Möglichkeit, den USt-Vorsteuerabzug für die Rechnung geltend zu machen -- eine unmittelbare finanzielle Folge für den Käufer, nicht nur ein administratives Versehen des Verkäufers.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Indonesia' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '⚠️ Bußgelder für nicht ausgestellte E-Rechnungen und verspätete USt-Erklärungen', NULL, NULL, 'Die Nichterfüllung der Pflicht zur Ausstellung von E-Rechnungen zieht Verwaltungsbußgelder nach sich. Separat davon zieht die verspätete Einreichung der periodischen USt-Erklärung (SPT Masa PPN) ein festes Bußgeld von 500.000 IDR nach sich -- ein routinemäßiger, aber echter Kostenpunkt bei Versäumnis einer Einreichungsfrist, unabhängig von jeder rechnungsbezogenen Strafe.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Indonesia' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '🔒 Nicht freigegebene Rechnungen stützen keinen Vorsteuerabzug', NULL, NULL, 'Seit Coretax am 31. Dezember 2025 vollständig durchgesetzt wurde, ist die Freigabe der DJP eine rechtliche Voraussetzung für eine gültige Steuerrechnung. Eine von der DJP nicht freigegebene Rechnung kann den USt-Vorsteuerabzug des Käufers nicht stützen, und eine fehlerhafte Meldung oder Unterzahlung der Umsatzsteuer kann Strafen von bis zu 100 % des nicht gezahlten Betrags nach sich ziehen -- ein reales, spürbares Risiko, kein nominelles.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Indonesia' AND cd.section = 'penalties_related' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'de', 'Verspätete Einreichung der periodischen USt-Erklärung (SPT Masa PPN)', '500.000 IDR (fest)', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Indonesia' AND pr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'de', 'Fehlerhafte Meldung oder Unterzahlung der Umsatzsteuer', 'Bis zu 100 % des nicht gezahlten USt-Betrags', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Indonesia' AND pr.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Bestätigen Sie, dass Ihre PKP-Registrierung und Ihr Coretax-Konto aktiv sind', 'Jeder umsatzsteuerlich registrierte Steuerpflichtige (PKP) benötigt ein aktives Coretax-Konto -- prüfen Sie, ob Ihres registriert und zugänglich ist, bevor Sie sich für die Rechnungsausstellung darauf verlassen.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Indonesia' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Verlagern Sie Ihren Rechnungsworkflow auf einen mit Coretax verbundenen Kanal', 'Ob über das Webportal, den Desktop-Client oder eine Host-to-Host-Integration (H2H) -- prüfen Sie, ob Ihre Rechnungssoftware tatsächlich an Coretax übermittelt, statt sich auf einen eigenständigen Altprozess zu verlassen.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Indonesia' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Laden Sie jede Rechnung vor dem 20. des Folgemonats auf Coretax hoch', 'Die PER-11/PJ/2025 legte dies als feste Frist fest -- ein Versäumnis kostet den Käufer seinen USt-Vorsteuerabzug, behandeln Sie es also als Compliance-Frist, nicht als weiches Ziel.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Indonesia' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Integrieren Sie eine Echtzeit-DJP-Freigabeprüfung in Ihren Rechnungsausstellungsprozess', 'Seit dem 31. Dezember 2025 hat eine Rechnung keine Rechtswirkung, bis die DJP sie freigibt -- prüfen Sie, ob Ihr Prozess diese Freigabe abwartet, bevor eine Rechnung als endgültig gilt.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Indonesia' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Stellen Sie sicher, dass Ihr Kreditorenbuchhaltungsprozess Lieferantenrechnungen ohne gültige Coretax-Freigabe ablehnt', 'Eine Lieferantenrechnung ohne DJP-Freigabe und gültige NSFP kann Ihren USt-Vorsteuerabzug nicht stützen -- bauen Sie diese Prüfung in Ihren Kreditorenworkflow ein, nicht nur in Ihren eigenen Verkaufsprozess.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Indonesia' AND sp.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Beschränken Sie Ihren Papierrechnungs-Notfallplan streng auf bestätigte Systemausfälle', 'Papierrechnungen sind nur bei echten Coretax-Ausfällen zulässig -- lassen Sie sie nicht zu einer routinemäßigen Umgehung für ein langsames Onboarding oder ungelöste technische Probleme werden.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Indonesia' AND sp.sort_order = 5;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'de', 'Coretax DJP — Plattform für Echtzeit-E-Rechnungs-Freigabe und USt-Vorgänge' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Indonesia' AND pt.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'de', 'Direktorat Jenderal Pajak (DJP) — Generaldirektion für Steuern' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Indonesia' AND pt.sort_order = 1;

-- ==================== fr ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'fr', 'Dédouanement en temps réel par la DJP via Coretax depuis le 31 décembre 2025, après une obligation d''e-Faktur progressive ayant atteint une couverture nationale en 2016', 'Cette page d''analyse reflète les indications publiques de la DJP et les informations sectorielles disponibles début août 2026, et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Confirmez les exigences actuelles directement auprès de la DJP ou d''un conseiller fiscal indonésien avant de fonder vos décisions de conformité sur cette page.', 'Le système e-Faktur Pajak de l''Indonésie a exigé des factures électroniques de TVA par étapes à partir de 2014, atteignant une couverture nationale complète le 1er juillet 2016. La plateforme Coretax de la DJP a été lancée le 1er janvier 2025 et est devenue pleinement applicable à compter du 31 décembre 2025, faisant basculer l''Indonésie vers un véritable modèle de dédouanement en temps réel où l''approbation de la DJP est une condition légale préalable à la validité d''une facture.', 'Les factures Coretax sont créées au format XML et téléversées pour une validation en temps réel par la DJP ; une fois approuvée, la facture est délivrée à l''acheteur sous forme de PDF à code QR portant un numéro de série de facture fiscale (Nomor Seri Faktur Pajak, NSFP) généré automatiquement. Les entreprises peuvent accéder à Coretax via son portail web, un client de bureau ou une intégration Host-to-Host (H2H) pour les systèmes comptables d''entreprise. Les factures papier ne sont autorisées qu''en cas d''interruption confirmée du système -- sinon, toute facture fiscale doit passer par ce processus électronique validé par la DJP.', 'L''obligation de facturation électronique de l''Indonésie est quasi universelle : tout contribuable assujetti à la TVA (Pengusaha Kena Pajak, PKP) entre dans son champ d''application, couvrant les fournitures imposables B2B et B2G nationales, les factures d''exportation (émises en tant que factures de TVA à taux zéro) et les documents correctifs tels que les notes de crédit, les notes de débit et les annulations. Il n''existe pas d''exemption pour les petites entreprises ou par secteur comparable à celle d''autres pays couverts par ce suivi -- l''enregistrement en tant que PKP est en soi ce qui fait entrer une entreprise dans le champ d''application.', 'L''entrée en vigueur intégrale de Coretax étant récente -- effective seulement depuis le 31 décembre 2025 --, la plupart des PKP ont encore un véritable travail de mise en œuvre devant eux, qu''il s''agisse de vérifier que leur configuration e-Faktur existante a bien migré ou de construire un premier flux de facturation connecté à Coretax.', 'L''Indonésie appuie ses règles de facturation électronique et de déclaration de la TVA sur des sanctions réelles et documentées, allant de la perte du crédit de taxe en amont pour une facture téléversée en retard à des amendes proportionnelles à l''ampleur d''un impayé.', 'L''Indonésie exige des factures électroniques de TVA depuis 2014, atteignant la couverture nationale de l''e-Faktur le 1er juillet 2016. La plateforme Coretax de la DJP a été lancée le 1er janvier 2025, et la PER-11/PJ/2025 a déplacé la date limite de téléversement des factures au 20 du mois suivant. À compter du 31 décembre 2025, Coretax est devenu pleinement applicable : le dédouanement de la DJP est désormais une condition légale préalable à la validité d''une facture, et non un contrôle a posteriori. Les factures non dédouanées ne peuvent pas justifier les déductions de TVA en amont, et les erreurs de déclaration peuvent entraîner des sanctions allant jusqu''à 100 % de la TVA impayée.', '🇮🇩' FROM countries WHERE name_en = 'Indonesia';

