INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Format et norme', '[["Création de la facture", "XML, généré via Coretax ou un logiciel connecté à Coretax"], ["Validation", "Validation en temps réel par la DJP avant l''émission légale de la facture"], ["Format de livraison", "PDF à code QR, portant un numéro de série de facture fiscale (NSFP) généré automatiquement"], ["Canaux d''accès", "Portail web Coretax, client de bureau ou intégration Host-to-Host (H2H) pour les systèmes d''entreprise"]]', 'Les factures papier ne restent autorisées qu''en cas d''interruption confirmée du système -- considérez l''émission électronique via l''un des canaux de Coretax comme la norme, non l''exception.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Indonesia' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Identifiants et enregistrement', '[["Enregistrement du contribuable", "Pengusaha Kena Pajak (PKP) -- l''enregistrement à la TVA auprès de la DJP déclenche le champ d''application de la facturation électronique"], ["Compte Coretax", "Enregistré et activé via le portail Coretax DJP"], ["Numéro de série", "Nomor Seri Faktur Pajak (NSFP), généré automatiquement par Coretax lors de l''approbation"], ["Organisme responsable", "Direktorat Jenderal Pajak (DJP) -- Direction générale des impôts, ministère des Finances"]]', 'Les entreprises étrangères qui s''enregistrent à la TVA indonésienne entrent dans le champ d''application dans les mêmes conditions que les PKP nationaux, une fois enregistrées.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Indonesia' AND cd.section = 'file_format' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Contenu obligatoire et conservation', '[["Champs essentiels de la facture", "Identification fiscale de l''émetteur/acheteur, date de facturation, biens/services et montants de TVA détaillés, NSFP"], ["Base légale", "Règlements de la DJP dans le cadre de la loi indonésienne sur la TVA, y compris la PMK 131/Tahun 2024"], ["Documents correctifs", "Les notes de crédit, notes de débit et annulations doivent également être traitées via Coretax"], ["Conservation", "Conforme aux règles générales indonésiennes de conservation des documents comptables/fiscaux en vertu de la loi sur les dispositions fiscales générales (généralement 10 ans) -- confirmez le délai actuel auprès de la DJP ou d''un conseiller local"]]', 'Ne considérez pas la PMK 131/Tahun 2024 comme le seul fondement juridique de chaque règle ici -- la DJP a superposé plusieurs règlements (KEP-54/PJ/2025, PER-11/PJ/2025, PER-8/PJ/2025) au cadre de base de la loi sur la TVA.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Indonesia' AND cd.section = 'file_format' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'fr', 'Le flux de dédouanement Coretax', 'Une facture fiscale suit cette séquence sous Coretax -- la validation de la DJP intervient désormais avant que la facture soit juridiquement valable, et non après :', 'Il s''agit d''un véritable modèle de dédouanement : contrairement aux contrôles a posteriori de l''ancien système e-Faktur, une facture n''a aucun effet juridique -- et ne peut justifier le crédit de TVA en amont de l''acheteur -- tant que la DJP ne l''a pas dédouanée.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Indonesia';
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'Le vendeur génère la facture fiscale au format XML via Coretax (portail web, client de bureau ou intégration Host-to-Host)' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Indonesia' AND st.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'La facture est téléversée sur Coretax pour une validation en temps réel par la DJP' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Indonesia' AND st.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'La DJP valide la facture et lui attribue un numéro de série de facture fiscale (NSFP)' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Indonesia' AND st.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'Coretax délivre une version PDF à code QR de la facture dédouanée' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Indonesia' AND st.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'La facture est juridiquement valable et remise à l''acheteur -- ce n''est qu''à partir de ce moment qu''elle peut justifier le crédit de TVA en amont de l''acheteur' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Indonesia' AND st.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Ce qui est obligatoire aujourd''hui, par niveau', '[["Émission nationale d''e-Faktur", "Tout PKP, depuis le 1er juillet 2016"], ["Dédouanement en temps réel par Coretax", "Tout PKP, obligatoire depuis le 31 décembre 2025"], ["Canaux H2H/Desktop pour grands contribuables", "Toujours autorisés, mais alimentent désormais le dédouanement de Coretax plutôt que de fonctionner de façon indépendante"], ["Factures papier", "Autorisées uniquement en cas d''interruption confirmée du système"]]', 'Il convient de bien préciser quel niveau vous concerne : l''obligation de facturation électronique de l''Indonésie est réellement universelle depuis 2016, mais l''exigence de dédouanement -- l''approbation de la DJP avant la validité d''une facture -- n''est devenue pleinement applicable qu''à compter du 31 décembre 2025.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Indonesia' AND cd.section = 'scope_transmission' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Qui doit se conformer', '[["Enregistrement PKP", "Toute entreprise dépassant le seuil d''enregistrement à la TVA indonésienne doit s''enregistrer comme PKP et se conformer"], ["B2B et B2G nationaux", "Pleinement concernés -- fournitures imposables de biens et services"], ["Factures d''exportation", "Concernées, émises en tant que factures de TVA à taux zéro"], ["Documents correctifs", "Les notes de crédit, notes de débit et annulations doivent également être traitées via Coretax"]]', 'Il n''existe pas d''exemption générale pour les petites entreprises vis-à-vis de Coretax comparable à celle d''autres pays couverts par ce suivi -- l''enregistrement PKP lui-même est le déclencheur.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Indonesia' AND cd.section = 'scope_transmission' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '💰 Manquer l''échéance de téléversement du 20 fait perdre le crédit de TVA', NULL, NULL, 'Depuis la PER-11/PJ/2025 (22 mai 2025), les factures fiscales doivent être téléversées sur Coretax au plus tard le 20 du mois suivant leur émission. En cas de non-respect de cette échéance, l''acheteur perd le droit de réclamer le crédit de TVA en amont sur la facture -- une conséquence financière immédiate pour l''acheteur, et non un simple oubli administratif du vendeur.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Indonesia' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '⚠️ Amendes pour non-émission de factures électroniques et déclarations de TVA tardives', NULL, NULL, 'Le non-respect de l''obligation d''émettre des factures électroniques entraîne des amendes administratives. Par ailleurs, le dépôt tardif de la déclaration périodique de TVA (SPT Masa PPN) entraîne une amende fixe de 500 000 IDR -- un coût habituel mais réel en cas de non-respect d''une échéance de déclaration, indépendant de toute sanction au niveau de la facture.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Indonesia' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '🔒 Les factures non dédouanées ne peuvent justifier le crédit de taxe en amont', NULL, NULL, 'Depuis l''entrée en vigueur intégrale de Coretax le 31 décembre 2025, le dédouanement de la DJP est une condition légale préalable à la validité d''une facture fiscale. Une facture que la DJP n''a pas dédouanée ne peut justifier la déduction de la TVA en amont de l''acheteur, et une déclaration incorrecte ou un impayé de TVA peuvent entraîner des sanctions allant jusqu''à 100 % du montant impayé -- une exposition réelle et significative, non symbolique.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Indonesia' AND cd.section = 'penalties_related' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'Dépôt tardif de la déclaration périodique de TVA (SPT Masa PPN)', '500 000 IDR (fixe)', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Indonesia' AND pr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'Déclaration incorrecte ou impayé de TVA', 'Jusqu''à 100 % du montant de TVA impayé', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Indonesia' AND pr.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Vérifiez que votre enregistrement PKP et votre compte Coretax sont actifs', 'Tout contribuable assujetti à la TVA (PKP) a besoin d''un compte Coretax actif -- vérifiez que le vôtre est enregistré et accessible avant de vous y fier pour l''émission de factures.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Indonesia' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Faites passer votre flux de facturation par un canal connecté à Coretax', 'Que ce soit via le portail web, le client de bureau ou une intégration Host-to-Host (H2H), vérifiez que votre logiciel de facturation soumet réellement à Coretax plutôt que de s''appuyer sur un processus hérité autonome.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Indonesia' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Téléversez chaque facture sur Coretax avant le 20 du mois suivant', 'La PER-11/PJ/2025 a fixé cette échéance comme stricte -- la manquer coûte à l''acheteur son crédit de TVA en amont, traitez-la donc comme une échéance de conformité, pas comme un objectif souple.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Indonesia' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Intégrez un contrôle de dédouanement DJP en temps réel dans votre processus d''émission de factures', 'Depuis le 31 décembre 2025, une facture n''a aucun effet juridique tant que la DJP ne l''a pas dédouanée -- vérifiez que votre processus attend ce dédouanement avant de considérer une facture comme définitive.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Indonesia' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Vérifiez que votre processus comptes fournisseurs rejette les factures fournisseurs sans dédouanement Coretax valide', 'Une facture fournisseur sans dédouanement de la DJP et sans NSFP valide ne peut pas justifier votre crédit de TVA en amont -- intégrez ce contrôle à votre flux comptes fournisseurs, pas seulement à votre propre processus de vente.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Indonesia' AND sp.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Limitez strictement votre plan de secours en factures papier aux interruptions confirmées du système', 'La facturation papier n''est autorisée qu''en cas de véritables interruptions de Coretax -- ne la laissez pas devenir une solution de contournement habituelle pour une intégration lente ou des problèmes techniques non résolus.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Indonesia' AND sp.sort_order = 5;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'fr', 'Coretax DJP — plateforme de dédouanement des factures électroniques en temps réel et des opérations de TVA' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Indonesia' AND pt.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'fr', 'Direktorat Jenderal Pajak (DJP) — Direction générale des impôts' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Indonesia' AND pt.sort_order = 1;
